ner&quot;)</div></li><li class="li1"><div class="de1">buyCorner.CornerRadius = UDim.new(0, 8)</div></li><li class="li1"><div class="de1">buyCorner.Parent = buyBtn</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local statusLabel = Instance.new(&quot;TextLabel&quot;)</div></li><li class="li1"><div class="de1">statusLabel.Size = UDim2.new(1, -20, 0, 22)</div></li><li class="li1"><div class="de1">statusLabel.Position = UDim2.new(0, 10, 0, 158)</div></li><li class="li1"><div class="de1">statusLabel.BackgroundColor3 = Color3.fromRGB(20, 20, 20)</div></li><li class="li1"><div class="de1">statusLabel.TextColor3 = Color3.fromRGB(170, 170, 170)</div></li><li class="li1"><div class="de1">statusLabel.TextSize = 12</div></li><li class="li1"><div class="de1">statusLabel.Font = Enum.Font.Gotham</div></li><li class="li1"><div class="de1">statusLabel.Text = &quot;상태: 리모트 로딩중...&quot;</div></li><li class="li1"><div class="de1">statusLabel.Parent = frame</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local statusCorner = Instance.new(&quot;UICorner&quot;)</div></li><li class="li1"><div class="de1">statusCorner.CornerRadius = UDim.new(0, 6)</div></li><li class="li1"><div class="de1">statusCorner.Parent = statusLabel</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local dragging, dragInput, dragStart, startPos</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">frame.InputBegan:Connect(function(input)</div></li><li class="li1"><div class="de1">    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then</div></li><li class="li1"><div class="de1">        dragging = true</div></li><li class="li1"><div class="de1">        dragStart = input.Position</div></li><li class="li1"><div class="de1">        startPos = frame.Position</div></li><li class="li1"><div class="de1">        input.Changed:Connect(function()</div></li><li class="li1"><div class="de1">            if input.UserInputState == Enum.UserInputState.End then</div></li><li class="li1"><div class="de1">                dragging = false</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">        end)</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">frame.InputChanged:Connect(function(input)</div></li><li class="li1"><div class="de1">    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then</div></li><li class="li1"><div class="de1">        dragInput = input</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">UserInputService.InputChanged:Connect(function(input)</div></li><li class="li1"><div class="de1">    if input == dragInput and dragging then</div></li><li class="li1"><div class="de1">        local delta = input.Position - dragStart</div></li><li class="li1"><div class="de1">        frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- ================= 상태 =================</div></li><li class="li1"><div class="de1">local COLORS = {</div></li><li class="li1"><div class="de1">    idle = Color3.fromRGB(170, 170, 170),</div></li><li class="li1"><div class="de1">    ok   = Color3.fromRGB(80, 220, 120),</div></li><li class="li1"><div class="de1">    warn = Color3.fromRGB(240, 180, 60),</div></li><li class="li1"><div class="de1">    err  = Color3.fromRGB(240, 90, 90),</div></li><li class="li1"><div class="de1">}</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local lastStatus = nil</div></li><li class="li1"><div class="de1">local function setStatus(text, color)</div></li><li class="li1"><div class="de1">    if text == lastStatus then return end</div></li><li class="li1"><div class="de1">    lastStatus = text</div></li><li class="li1"><div class="de1">    statusLabel.Text = &quot;상태: &quot; .. text</div></li><li class="li1"><div class="de1">    statusLabel.TextColor3 = color or COLORS.idle</div></li><li class="li1"><div class="de1">end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local healRunning = false</div></li><li class="li1"><div class="de1">local switchRunning = false</div></li><li class="li1"><div class="de1">local buyRunning = false</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local lastFire = 0</div></li><li class="li1"><div class="de1">local cycleBusy = false</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local function setHealState(on)</div></li><li class="li1"><div class="de1">    healRunning = on</div></li><li class="li1"><div class="de1">    healBtn.Text = on and &quot;Auto Heal: ON&quot; or &quot;Auto Heal: OFF&quot;</div></li><li class="li1"><div class="de1">    healBtn.BackgroundColor3 = on and Color3.fromRGB(230, 60, 60) or Color3.fromRGB(0, 162, 255)</div></li><li class="li1"><div class="de1">end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local function setSwitchState(on)</div></li><li class="li1"><div class="de1">    switchRunning = on</div></li><li class="li1"><div class="de1">    switchBtn.Text = on and &quot;Auto Switch: ON&quot; or &quot;Auto Switch: OFF&quot;</div></li><li class="li1"><div class="de1">    switchBtn.BackgroundColor3 = on and Color3.fromRGB(0, 200, 100) or Color3.fromRGB(80, 80, 80)</div></li><li class="li1"><div class="de1">end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local function setBuyState(on)</div></li><li class="li1"><div class="de1">    buyRunning = on</div></li><li class="li1"><div class="de1">    buyBtn.Text = on and &quot;Auto Buy: ON&quot; or &quot;Auto Buy: OFF&quot;</div></li><li class="li1"><div class="de1">    buyBtn.BackgroundColor3 = on and Color3.fromRGB(160, 60, 220) or Color3.fromRGB(80, 80, 80)</div></li><li class="li1"><div class="de1">end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local function fireHeal(char, tool)</div></li><li class="li1"><div class="de1">    pcall(function()</div></li><li class="li1"><div class="de1">        netPlayGuitar:FireServer({</div></li><li class="li1"><div class="de1">            healTarget = char,</div></li><li class="li1"><div class="de1">            tool = tool,</div></li><li class="li1"><div class="de1">        })</div></li><li class="li1"><div class="de1">    end)</div></li><li class="li1"><div class="de1">end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- ============ Auto Heal ============</div></li><li class="li1"><div class="de1">local function toggleHeal()</div></li><li class="li1"><div class="de1">    if not netPlayGuitar then</div></li><li class="li1"><div class="de1">        healBtn.Text = &quot;Remote Not Found&quot;</div></li><li class="li1"><div class="de1">        return</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">    setHealState(not healRunning)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">    if healRunning then</div></li><li class="li1"><div class="de1">        task.spawn(function()</div></li><li class="li1"><div class="de1">            while healRunning do</div></li><li class="li1"><div class="de1">                local char = LocalPlayer.Character</div></li><li class="li1"><div class="de1">                if char and char:FindFirstChild(&quot;Humanoid&quot;) and char.Humanoid.Health &gt; 0 then</div></li><li class="li1"><div class="de1">                    if switchRunning then</div></li><li class="li1"><div class="de1">                        task.wait(0.3)</div></li><li class="li1"><div class="de1">                    else</div></li><li class="li1"><div class="de1">                        local _, g = getGuitarItem()</div></li><li class="li1"><div class="de1">                        fireHeal(char, g or char:FindFirstChildOfClass(&quot;Tool&quot;))</div></li><li class="li1"><div class="de1">                        task.wait(0.25)</div></li><li class="li1"><div class="de1">                    end</div></li><li class="li1"><div class="de1">                else</div></li><li class="li1"><div class="de1">                    task.wait(0.25)</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">        end)</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end</div></li><li class="li1"><div class="de1">healBtn.MouseButton1Click:Connect(toggleHeal)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- ============ Auto Buy ============</div></li><li class="li1"><div class="de1">local purchaseConfig = {</div></li><li class="li1"><div class="de1">    priority = 1,</div></li><li class="li1"><div class="de1">    item = &quot;guitar&quot;,</div></li><li class="li1"><div class="de1">    amount = 1,</div></li><li class="li1"><div class="de1">    after = 1</div></li><li class="li1"><div class="de1">}</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local function buyGuitar()</div></li><li class="li1"><div class="de1">    if not netPurchaseItem then return end</div></li><li class="li1"><div class="de1">    local args = {</div></li><li class="li1"><div class="de1">        {</div></li><li class="li1"><div class="de1">            shopItem = {</div></li><li class="li1"><div class="de1">                amount = 1,</div></li><li class="li1"><div class="de1">                lockAfterPurchase = true,</div></li><li class="li1"><div class="de1">                itemType = &quot;guitar&quot;,</div></li><li class="li1"><div class="de1">                category = &quot;Combat&quot;,</div></li><li class="li1"><div class="de1">                price = 16,</div></li><li class="li1"><div class="de1">                requiresKit = { &quot;melody&quot; },</div></li><li class="li1"><div class="de1">                spawnWithItems = { &quot;guitar&quot; },</div></li><li class="li1"><div class="de1">                currency = &quot;iron&quot;</div></li><li class="li1"><div class="de1">            },</div></li><li class="li1"><div class="de1">            shopId = &quot;1_item_shop&quot;</div></li><li class="li1"><div class="de1">        }</div></li><li class="li1"><div class="de1">    }</div></li><li class="li1"><div class="de1">    netPurchaseItem:InvokeServer(unpack(args))</div></li><li class="li1"><div class="de1">end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">local function toggleBuy()</div></li><li class="li1"><div class="de1">    setBuyState(not buyRunning)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">    if buyRunning then</div></li><li class="li1"><div class="de1">        task.spawn(function()</div></li><li class="li1"><div class="de1">            while buyRunning do</div></li><li class="li1"><div class="de1">                if purchaseConfig.after == 1 then</div></li><li class="li1"><div class="de1">                    local character = LocalPlayer.Character</div></li><li class="li1"><div class="de1">                    local backpack = LocalPlayer:FindFirstChild(&quot;Backpack&quot;)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                    local function checkItem(container)</div></li><li class="li1"><div class="de1">                        if not container then return false end</div></li><li class="li1"><div class="de1">                        for _, item in ipairs(container:GetChildren()) do</div></li><li class="li1"><div class="de1">                            if string.lower(item.Name) == string.lower(purchaseConfig.item) then</div></li><li class="li1"><div class="de1">                                return true</div></li><li class="li1"><div class="de1">                            end</div></li><li class="li1"><div class="de1">                        end</div></li><li class="li1"><div class="de1">                        return false</div></li><li class="li1"><div class="de1">                    end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                    local hasGuitar = checkItem(character) or checkItem(backpack)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                    if not hasGuitar then</div></li><li class="li1"><div class="de1">                        pcall(buyGuitar)</div></li><li class="li1"><div class="de1">                        task.wait(0.5)</div></li><li class="li1"><div class="de1">                    end</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">                task.wait(0.5)</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">      